using System.Data.Common;
using System.Text;
using System.Text.Json;
using BarberSync.Api.Security;
using BarberSync.Api.Services.Catalog;
using BarberSync.Api.Services.Team;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace BarberSync.Api.Controllers;

[ApiController, Authorize]
public abstract class CatalogControllerBase(TeamDataService data) : ControllerBase
{
    protected TeamDataService Data => data;
    protected object Envelope(object? value) => new { success=true, data=value, traceId=HttpContext.TraceIdentifier };
    protected IActionResult Invalid(string detail) => Problem(statusCode:422,title:"Dados de catálogo inválidos",detail:detail,extensions:new Dictionary<string,object?>{{"traceId",HttpContext.TraceIdentifier}});
    protected static void Add(DbCommand command,string name,object? value)=>TeamDataService.Add(command,name,value);
}

[Route("api/catalog")]
public sealed class CatalogController(TeamDataService data) : CatalogControllerBase(data)
{
    [HttpGet("dashboard"),RequirePermission("Catalog.Read")]
    public async Task<IActionResult> Dashboard(CancellationToken ct)=>Ok(Envelope((await Data.QueryAsync(@"select
      (select count(*) from barber.catalog_service_profiles where tenant_id=@tenant and branch_id=@branch and deleted_at is null) services,
      (select count(*) from barber.catalog_product_profiles where tenant_id=@tenant and branch_id=@branch and deleted_at is null) products,
      (select count(*) from barber.catalog_combo_definitions where tenant_id=@tenant and branch_id=@branch and status='Active') active_combos,
      (select count(*) from barber.catalog_package_definitions where tenant_id=@tenant and branch_id=@branch and status='Active') active_packages,
      (select count(*) from barber.catalog_service_profiles where tenant_id=@tenant and branch_id=@branch and estimated_margin_percent<20 and deleted_at is null)+(select count(*) from barber.catalog_product_profiles where tenant_id=@tenant and branch_id=@branch and margin_percent<20 and deleted_at is null) margin_alerts,
      (select coalesce(sum(commission_amount),0) from barber.catalog_commission_events where tenant_id=@tenant and branch_id=@branch and status='Payable') commission_payable",null,ct)).Single()));
    [HttpGet("filter-options"),RequirePermission("Catalog.Read")]
    public async Task<IActionResult> Options(CancellationToken ct)=>Ok(Envelope(new { services=await Data.QueryAsync("select id,name from barber.services where tenant_id=@tenant and branch_id=@branch and status='Active' and deleted_at is null order by name",null,ct), products=await Data.QueryAsync("select id,name from barber.products where tenant_id=@tenant and branch_id=@branch and status='Active' and deleted_at is null order by name",null,ct), professionals=await Data.QueryAsync("select id,name from barber.professionals where tenant_id=@tenant and branch_id=@branch and status='Active' and deleted_at is null order by name",null,ct), partners=await Data.QueryAsync("select id,name from barber.partner_profiles where tenant_id=@tenant and branch_id=@branch and status='Active' and deleted_at is null order by name",null,ct), categories=await Data.QueryAsync("select id,name from barber.product_categories where tenant_id=@tenant and branch_id=@branch order by name",null,ct), suppliers=await Data.QueryAsync("select id,name from barber.suppliers where tenant_id=@tenant and branch_id=@branch and status='Active' and deleted_at is null order by name",null,ct) }));
}

[Route("api/catalog/services")]
public sealed class CatalogServicesController(TeamDataService data, ICurrentUserContext current):CatalogControllerBase(data)
{
 [HttpGet,RequirePermission("Catalog.Read")] public async Task<IActionResult> List(CancellationToken ct)=>Ok(Envelope(await Data.QueryAsync("select p.*,s.name,s.description from barber.catalog_service_profiles p join barber.services s on s.id=p.service_id where p.tenant_id=@tenant and p.branch_id=@branch and p.deleted_at is null order by s.name",null,ct)));
 [HttpPost("profile"),RequirePermission("Catalog.Services.Manage")] public Task<IActionResult> Create(CatalogServiceProfileRequest r,CancellationToken ct)=>Save(null,r,ct);
 [HttpPut("{id:guid}/profile"),RequirePermission("Catalog.Services.Manage")] public Task<IActionResult> Update(Guid id,CatalogServiceProfileRequest r,CancellationToken ct)=>Save(id,r,ct);
 async Task<IActionResult> Save(Guid? id,CatalogServiceProfileRequest r,CancellationToken ct){if(r.ServiceId==Guid.Empty||r.BasePrice<0||r.EstimatedCost<0||r.DefaultDurationMinutes<=0)return Invalid("Selecione um serviço e informe preço, custo e duração válidos.");var entity=id??Guid.NewGuid();var sql=id is null?"insert into barber.catalog_service_profiles(id,tenant_id,branch_id,service_id,category_id,base_price,estimated_cost,estimated_margin_percent,default_duration_minutes,public_visible,kiosk_visible,marketplace_visible,requires_consent,requires_anamnesis,status,created_by) select @id,@tenant,@branch,id,@category,@price,@cost,case when @price=0 then 0 else (@price-@cost)/@price*100 end,@duration,@public,@kiosk,@marketplace,@consent,@anamnesis,@status,@user from barber.services where id=@service and tenant_id=@tenant and branch_id=@branch and deleted_at is null":"update barber.catalog_service_profiles set category_id=@category,base_price=@price,estimated_cost=@cost,estimated_margin_percent=case when @price=0 then 0 else (@price-@cost)/@price*100 end,default_duration_minutes=@duration,public_visible=@public,kiosk_visible=@kiosk,marketplace_visible=@marketplace,requires_consent=@consent,requires_anamnesis=@anamnesis,status=@status,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and deleted_at is null";await Data.WriteAsync(sql,id is null?"CatalogServiceCreated":"CatalogServiceUpdated","catalog_service_profiles",entity,r.Reason,c=>{Add(c,"service",r.ServiceId);Add(c,"category",r.CategoryId);Add(c,"price",r.BasePrice);Add(c,"cost",r.EstimatedCost);Add(c,"duration",r.DefaultDurationMinutes);Add(c,"public",r.PublicVisible);Add(c,"kiosk",r.KioskVisible);Add(c,"marketplace",r.MarketplaceVisible);Add(c,"consent",r.RequiresConsent);Add(c,"anamnesis",r.RequiresAnamnesis);Add(c,"status",r.Status);Add(c,"user",current.UserId);},ct);return id is null?Created($"/api/catalog/services/{entity}/profile",Envelope(new{id=entity})):Ok(Envelope(new{id=entity}));}
}

[Route("api/catalog/products")]
public sealed class CatalogProductsController(TeamDataService data,ICurrentUserContext current):CatalogControllerBase(data)
{
 [HttpGet,RequirePermission("Catalog.Read")] public async Task<IActionResult> List(CancellationToken ct)=>Ok(Envelope(await Data.QueryAsync("select c.*,p.name,p.current_stock stock from barber.catalog_product_profiles c join barber.products p on p.id=c.product_id where c.tenant_id=@tenant and c.branch_id=@branch and c.deleted_at is null order by p.name",null,ct)));
 [HttpPost("profile"),RequirePermission("Catalog.Products.Manage")] public Task<IActionResult> Create(CatalogProductProfileRequest r,CancellationToken ct)=>Save(null,r,ct);
 [HttpPut("{id:guid}/profile"),RequirePermission("Catalog.Products.Manage")] public Task<IActionResult> Update(Guid id,CatalogProductProfileRequest r,CancellationToken ct)=>Save(id,r,ct);
 async Task<IActionResult> Save(Guid? id,CatalogProductProfileRequest r,CancellationToken ct){if(r.ProductId==Guid.Empty||r.CostPrice<0||r.SalePrice<0)return Invalid("Selecione um produto e informe custo e preço válidos.");var entity=id??Guid.NewGuid();var sql=id is null?"insert into barber.catalog_product_profiles(id,tenant_id,branch_id,product_id,category_id,supplier_id,cost_price,sale_price,margin_percent,public_visible,marketplace_visible,stock_control_required,status,created_by) select @id,@tenant,@branch,id,@category,@supplier,@cost,@price,case when @price=0 then 0 else (@price-@cost)/@price*100 end,@public,@marketplace,@stock,@status,@user from barber.products where id=@product and tenant_id=@tenant and branch_id=@branch and deleted_at is null":"update barber.catalog_product_profiles set category_id=@category,supplier_id=@supplier,cost_price=@cost,sale_price=@price,margin_percent=case when @price=0 then 0 else (@price-@cost)/@price*100 end,public_visible=@public,marketplace_visible=@marketplace,stock_control_required=@stock,status=@status,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and deleted_at is null";await Data.WriteAsync(sql,id is null?"CatalogProductCreated":"CatalogProductUpdated","catalog_product_profiles",entity,r.Reason,c=>{Add(c,"product",r.ProductId);Add(c,"category",r.CategoryId);Add(c,"supplier",r.SupplierId);Add(c,"cost",r.CostPrice);Add(c,"price",r.SalePrice);Add(c,"public",r.PublicVisible);Add(c,"marketplace",r.MarketplaceVisible);Add(c,"stock",r.StockControlRequired);Add(c,"status",r.Status);Add(c,"user",current.UserId);},ct);return id is null?Created($"/api/catalog/products/{entity}/profile",Envelope(new{id=entity})):Ok(Envelope(new{id=entity}));}
}

[Route("api/catalog/combos")]
public sealed class CatalogCombosController(TeamDataService data,ICurrentUserContext current):CatalogControllerBase(data)
{
 [HttpGet,RequirePermission("Catalog.Read")] public async Task<IActionResult> List(CancellationToken ct)=>Ok(Envelope(await Data.QueryAsync("select c.*,coalesce(jsonb_agg(jsonb_build_object('id',i.id,'itemType',i.item_type,'quantity',i.quantity,'unitPrice',i.unit_price_snapshot)) filter(where i.id is not null),'[]') items from barber.catalog_combo_definitions c left join barber.catalog_combo_items i on i.combo_id=c.id where c.tenant_id=@tenant and c.branch_id=@branch and c.deleted_at is null group by c.id order by c.updated_at desc",null,ct)));
 [HttpPost,RequirePermission("Catalog.Combos.Manage")] public Task<IActionResult> Create(CatalogBundleRequest r,CancellationToken ct)=>Save(null,r,ct);
 [HttpPut("{id:guid}"),RequirePermission("Catalog.Combos.Manage")] public Task<IActionResult> Update(Guid id,CatalogBundleRequest r,CancellationToken ct)=>Save(id,r,ct);
 async Task<IActionResult> Save(Guid? id,CatalogBundleRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||r.Price<0||r.Items.Count==0||r.Items.Any(x=>x.Quantity<=0||x.UnitPrice<0))return Invalid("O combo exige nome, preço e ao menos um item válido.");var baseTotal=r.Items.Sum(x=>x.Quantity*x.UnitPrice);if(r.Price>baseTotal)return Invalid("O preço do combo não pode exceder o total sem uma regra de acréscimo.");var entity=id??Guid.NewGuid();await Data.WriteAsync(id is null?"insert into barber.catalog_combo_definitions(id,tenant_id,branch_id,name,description,base_total,combo_price,margin_percent,status,public_visible,kiosk_visible,marketplace_visible,created_by) values(@id,@tenant,@branch,@name,@description,@base,@price,case when @price=0 then 0 else (@price-@cost)/@price*100 end,'Draft',@public,@kiosk,@marketplace,@user)":"update barber.catalog_combo_definitions set name=@name,description=@description,base_total=@base,combo_price=@price,margin_percent=case when @price=0 then 0 else (@price-@cost)/@price*100 end,public_visible=@public,kiosk_visible=@kiosk,marketplace_visible=@marketplace,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and status<>'Archived'","CatalogComboSaved","catalog_combo_definitions",entity,r.Reason,c=>{Add(c,"name",r.Name.Trim());Add(c,"description",r.Description);Add(c,"base",baseTotal);Add(c,"price",r.Price);Add(c,"cost",r.Items.Sum(x=>x.Quantity*x.Cost));Add(c,"public",r.PublicVisible);Add(c,"kiosk",r.KioskVisible);Add(c,"marketplace",r.MarketplaceVisible);Add(c,"user",current.UserId);},ct);await Data.WriteAsync("delete from barber.catalog_combo_items where combo_id=@combo and tenant_id=@tenant and branch_id=@branch; insert into barber.catalog_combo_items(id,tenant_id,branch_id,combo_id,item_type,service_id,product_id,quantity,unit_price_snapshot,cost_snapshot,sort_order) select gen_random_uuid(),@tenant,@branch,@combo,x.item_type,x.service_id,x.product_id,x.quantity,x.unit_price,x.cost,x.sort_order from jsonb_to_recordset(@items::jsonb) x(item_type varchar,service_id uuid,product_id uuid,quantity numeric,unit_price numeric,cost numeric,sort_order int)","CatalogComboItemsSaved","catalog_combo_definitions",entity,r.Reason,c=>{Add(c,"combo",entity);Add(c,"items",JsonSerializer.Serialize(r.Items.Select((x,i)=>new{item_type=x.ItemType,service_id=x.ServiceId,product_id=x.ProductId,quantity=x.Quantity,unit_price=x.UnitPrice,cost=x.Cost,sort_order=i})));},ct);return Ok(Envelope(new{id=entity,status="Draft",baseTotal}));}
 [HttpPost("{id:guid}/activate"),RequirePermission("Catalog.Combos.Manage")] public Task<IActionResult> Activate(Guid id,CatalogReasonRequest r,CancellationToken ct)=>State(id,"Active",r,ct);
 [HttpPost("{id:guid}/archive"),RequirePermission("Catalog.Combos.Manage")] public Task<IActionResult> Archive(Guid id,CatalogReasonRequest r,CancellationToken ct)=>State(id,"Archived",r,ct);
 async Task<IActionResult> State(Guid id,string state,CatalogReasonRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Reason))return Invalid("Informe o motivo da alteração.");await Data.WriteAsync("update barber.catalog_combo_definitions c set status=@status,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and deleted_at is null and (@status='Archived' or exists(select 1 from barber.catalog_combo_items i where i.combo_id=c.id))","CatalogComboStatusChanged","catalog_combo_definitions",id,r.Reason,c=>Add(c,"status",state),ct);return Ok(Envelope(new{id,status=state}));}
}

