 [HttpGet,RequirePermission("Catalog.Read")] public async Task<IActionResult> List(CancellationToken ct)=>Ok(Envelope(await Data.QueryAsync("select * from barber.catalog_package_definitions where tenant_id=@tenant and branch_id=@branch and deleted_at is null order by updated_at desc",null,ct)));
 [HttpPost,RequirePermission("Catalog.Packages.Manage")] public Task<IActionResult> Create(CatalogPackageRequest r,CancellationToken ct)=>Save(null,r,ct);
 [HttpPut("{id:guid}"),RequirePermission("Catalog.Packages.Manage")] public Task<IActionResult> Update(Guid id,CatalogPackageRequest r,CancellationToken ct)=>Save(id,r,ct);
 async Task<IActionResult> Save(Guid? id,CatalogPackageRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||r.Price<0||r.ValidityDays<=0||r.Items.Count==0||r.Items.Any(x=>x.Quantity<=0))return Invalid("Pacote exige nome, validade, preço e itens com saldo positivo.");var entity=id??Guid.NewGuid();await Data.WriteAsync(id is null?"insert into barber.catalog_package_definitions(id,tenant_id,branch_id,name,description,package_type,price,validity_days,status,public_visible,kiosk_visible,marketplace_visible,created_by) values(@id,@tenant,@branch,@name,@description,@type,@price,@validity,'Draft',@public,@kiosk,@marketplace,@user)":"update barber.catalog_package_definitions set name=@name,description=@description,package_type=@type,price=@price,validity_days=@validity,public_visible=@public,kiosk_visible=@kiosk,marketplace_visible=@marketplace,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and status<>'Archived'","CatalogPackageSaved","catalog_package_definitions",entity,r.Reason,c=>{Add(c,"name",r.Name.Trim());Add(c,"description",r.Description);Add(c,"type",r.PackageType);Add(c,"price",r.Price);Add(c,"validity",r.ValidityDays);Add(c,"public",r.PublicVisible);Add(c,"kiosk",r.KioskVisible);Add(c,"marketplace",r.MarketplaceVisible);Add(c,"user",current.UserId);},ct);await Data.WriteAsync("delete from barber.catalog_package_items where package_id=@package and tenant_id=@tenant and branch_id=@branch; insert into barber.catalog_package_items(id,tenant_id,branch_id,package_id,item_type,service_id,product_id,quantity,unit_price_snapshot) select gen_random_uuid(),@tenant,@branch,@package,x.item_type,x.service_id,x.product_id,x.quantity,x.unit_price from jsonb_to_recordset(@items::jsonb) x(item_type varchar,service_id uuid,product_id uuid,quantity numeric,unit_price numeric)","CatalogPackageItemsSaved","catalog_package_definitions",entity,r.Reason,c=>{Add(c,"package",entity);Add(c,"items",JsonSerializer.Serialize(r.Items.Select(x=>new{item_type=x.ItemType,service_id=x.ServiceId,product_id=x.ProductId,quantity=x.Quantity,unit_price=x.UnitPrice})));},ct);return Ok(Envelope(new{id=entity,status="Draft"}));}
 [HttpPost("{id:guid}/activate"),RequirePermission("Catalog.Packages.Manage")] public Task<IActionResult> Activate(Guid id,CatalogReasonRequest r,CancellationToken ct)=>State(id,"Active",r,ct); [HttpPost("{id:guid}/archive"),RequirePermission("Catalog.Packages.Manage")] public Task<IActionResult> Archive(Guid id,CatalogReasonRequest r,CancellationToken ct)=>State(id,"Archived",r,ct);
 async Task<IActionResult> State(Guid id,string status,CatalogReasonRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Reason))return Invalid("Informe o motivo da alteração.");await Data.WriteAsync("update barber.catalog_package_definitions set status=@status,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and deleted_at is null","CatalogPackageStatusChanged","catalog_package_definitions",id,r.Reason,c=>Add(c,"status",status),ct);return Ok(Envelope(new{id,status}));}
}

[Route("api/catalog/pricing-rules")]
public sealed class CatalogPricingRulesController(TeamDataService data,ICurrentUserContext current):CatalogControllerBase(data)
{
 [HttpGet,RequirePermission("Catalog.Read")] public async Task<IActionResult> List(CancellationToken ct)=>Ok(Envelope(await Data.QueryAsync("select * from barber.catalog_price_rules where tenant_id=@tenant and branch_id=@branch and deleted_at is null order by priority desc,created_at desc",null,ct)));
 [HttpPost,RequirePermission("Catalog.Pricing.Manage")] public Task<IActionResult> Create(CatalogPricingRuleRequest r,CancellationToken ct)=>Save(null,r,ct); [HttpPut("{id:guid}"),RequirePermission("Catalog.Pricing.Manage")] public Task<IActionResult> Update(Guid id,CatalogPricingRuleRequest r,CancellationToken ct)=>Save(id,r,ct);
 async Task<IActionResult> Save(Guid? id,CatalogPricingRuleRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Name)||(r.EndsAt.HasValue&&r.StartsAt.HasValue&&r.EndsAt.Value<=r.StartsAt.Value)||r.Priority<0)return Invalid("Informe nome, prioridade e vigência coerente.");var entity=id??Guid.NewGuid();await Data.WriteAsync(id is null?"insert into barber.catalog_price_rules(id,tenant_id,branch_id,name,rule_type,priority,starts_at,ends_at,status,settings_json,created_by) values(@id,@tenant,@branch,@name,@type,@priority,@starts,@ends,'Draft',@settings::jsonb,@user)":"update barber.catalog_price_rules set name=@name,rule_type=@type,priority=@priority,starts_at=@starts,ends_at=@ends,settings_json=@settings::jsonb,updated_at=now() where id=@id and tenant_id=@tenant and branch_id=@branch and status<>'Archived'","CatalogPricingRuleSaved","catalog_price_rules",entity,r.Reason,c=>{Add(c,"name",r.Name.Trim());Add(c,"type",r.RuleType);Add(c,"priority",r.Priority);Add(c,"starts",r.StartsAt);Add(c,"ends",r.EndsAt);Add(c,"settings",r.Settings.GetRawText());Add(c,"user",current.UserId);},ct);return Ok(Envelope(new{id=entity,status="Draft"}));}
