 [HttpPost("simulate-commission"),RequirePermission("Catalog.Read")] public async Task<IActionResult> Commission(CatalogCommissionRequest r,CancellationToken ct){try{return Ok(Envelope(await simulator.Commission(r,ct)));}catch(ArgumentException e){return Invalid(e.Message);}}
}
[Route("api/catalog/audit")]
public sealed class CatalogAuditController(TeamDataService data):CatalogControllerBase(data){[HttpGet,RequirePermission("Catalog.Read")]public async Task<IActionResult> List(CancellationToken ct)=>Ok(Envelope(await Data.QueryAsync("select * from barber.catalog_audit_events where tenant_id=@tenant and branch_id=@branch order by created_at desc limit 500",null,ct)));}
[Route("api/catalog/reports")]
public sealed class CatalogReportsController(TeamDataService data):CatalogControllerBase(data){[HttpGet("export"),RequirePermission("Catalog.Reports.Export")]public async Task<IActionResult> Export(CancellationToken ct){var rows=await Data.QueryAsync("select item_type,item_id,old_price,new_price,reason,changed_at from barber.catalog_price_history where tenant_id=@tenant and branch_id=@branch order by changed_at desc",null,ct);var csv=new StringBuilder("tipo;item;preco_anterior;preco_novo;motivo;alterado_em\r\n");foreach(var row in rows)csv.AppendLine(string.Join(';',row.Values.Select(x=>$"\"{Convert.ToString(x)?.Replace("\"","\"\"")}\"")));return File(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(csv.ToString())).ToArray(),"text/csv",$"catalogo-{DateTime.UtcNow:yyyyMMdd}.csv");}}

[ApiController,Authorize,Route("api/mobile/catalog")]
public sealed class MobileCatalogController(TeamDataService data,CatalogSimulationService simulator):ControllerBase
{
 object Out(object value)=>new{success=true,data=value,sourceStatus="available",traceId=HttpContext.TraceIdentifier};
 [HttpGet("services")]public async Task<IActionResult> Services(CancellationToken ct)=>Ok(Out(await data.QueryAsync("select p.service_id id,s.name,s.description,p.base_price price,p.default_duration_minutes duration_minutes from barber.catalog_service_profiles p join barber.services s on s.id=p.service_id where p.tenant_id=@tenant and p.branch_id=@branch and p.status='Active' and p.public_visible and s.status='Active' and p.deleted_at is null",null,ct)));
 [HttpGet("products")]public async Task<IActionResult> Products(CancellationToken ct)=>Ok(Out(await data.QueryAsync("select p.product_id id,x.name,p.sale_price price from barber.catalog_product_profiles p join barber.products x on x.id=p.product_id where p.tenant_id=@tenant and p.branch_id=@branch and p.status='Active' and p.public_visible and x.status='Active' and p.deleted_at is null and (not p.stock_control_required or x.current_stock>0)",null,ct)));
 [HttpGet("combos")]public async Task<IActionResult> Combos(CancellationToken ct)=>Ok(Out(await data.QueryAsync("select id,name,description,combo_price price from barber.catalog_combo_definitions where tenant_id=@tenant and branch_id=@branch and status='Active' and public_visible and deleted_at is null and not exists(select 1 from barber.catalog_combo_items i left join barber.catalog_service_profiles s on s.service_id=i.service_id left join barber.catalog_product_profiles p on p.product_id=i.product_id where i.combo_id=catalog_combo_definitions.id and coalesce(s.status,p.status,'Inactive')<>'Active')",null,ct)));
 [HttpPost("simulate-price")]public async Task<IActionResult> Price(CatalogPriceRequest r,CancellationToken ct)=>Ok(Out(await simulator.Price(r,ct)));
}

public sealed record CatalogServiceProfileRequest(Guid ServiceId,Guid? CategoryId,decimal BasePrice,decimal EstimatedCost,int DefaultDurationMinutes,bool PublicVisible,bool KioskVisible,bool MarketplaceVisible,bool RequiresConsent,bool RequiresAnamnesis,string Status,string? Reason);
public sealed record CatalogProductProfileRequest(Guid ProductId,Guid? CategoryId,Guid? SupplierId,decimal CostPrice,decimal SalePrice,bool PublicVisible,bool MarketplaceVisible,bool StockControlRequired,string Status,string? Reason);
public sealed record CatalogBundleItem(string ItemType,Guid? ServiceId,Guid? ProductId,decimal Quantity,decimal UnitPrice,decimal Cost);
public sealed record CatalogBundleRequest(string Name,string? Description,decimal Price,bool PublicVisible,bool KioskVisible,bool MarketplaceVisible,IReadOnlyList<CatalogBundleItem> Items,string? Reason);
public sealed record CatalogPackageRequest(string Name,string? Description,string PackageType,decimal Price,int ValidityDays,bool PublicVisible,bool KioskVisible,bool MarketplaceVisible,IReadOnlyList<CatalogBundleItem> Items,string? Reason);
public sealed record CatalogPricingRuleRequest(string Name,string RuleType,int Priority,DateTimeOffset? StartsAt,DateTimeOffset? EndsAt,JsonElement Settings,string? Reason);
public sealed record CatalogMarginRuleRequest(string Name,string TargetType,Guid? TargetId,decimal MinimumMarginPercent,string ActionType,string? Reason);
public sealed record CatalogCommissionRuleRequest(string Name,string OwnerType,Guid OwnerId,string TargetType,Guid TargetId,string CommissionType,decimal? Amount,decimal? Percent,string TriggerType,string? Reason);
public sealed record CatalogReasonRequest(string Reason);
